// Unity build of the vendored Draco glTF-bitstream decoder. Draco ships as a
// tree of .cc files (no single-header form); we compile the decode-only subset
// through this one translation unit, mirroring meshoptimizer_impl.cpp. The
// subset and its header closure are regenerated by the recipe in
// vendor/README.md — do not hand-edit the file list.
//
// Suppress warnings from vendored code on GCC/Clang/MSVC; upstream code is not
// audited against this project's strict -Werror flag set (refresh from upstream
// instead of fixing warnings here).
#ifdef __GNUC__
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wconversion"
#pragma GCC diagnostic ignored "-Wsign-conversion"
#pragma GCC diagnostic ignored "-Wsign-compare"
#pragma GCC diagnostic ignored "-Wfloat-conversion"
#pragma GCC diagnostic ignored "-Wdouble-promotion"
#pragma GCC diagnostic ignored "-Wold-style-cast"
#pragma GCC diagnostic ignored "-Wshadow"
#pragma GCC diagnostic ignored "-Wcast-align"
#pragma GCC diagnostic ignored "-Wunused-parameter"
#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-local-typedefs"
#pragma GCC diagnostic ignored "-Wcomment"
#pragma GCC diagnostic ignored "-Wredundant-move"
#pragma GCC diagnostic ignored "-Wignored-qualifiers"
#pragma GCC diagnostic ignored "-Wrange-loop-construct"
#pragma GCC diagnostic ignored "-Wpedantic"
#if !defined(__clang__)
#pragma GCC diagnostic ignored "-Wuseless-cast"
#pragma GCC diagnostic ignored "-Wduplicated-branches"
#pragma GCC diagnostic ignored "-Wmaybe-uninitialized"
#endif
#elif defined(_MSC_VER)
#pragma warning(push)
#pragma warning(disable : 4018 4244 4245 4267 4146)
#endif

#include "src/draco/attributes/attribute_octahedron_transform.cc"
